class SegChequeointegridadModel extends ZendExt_Model
{

    public function SegChequeointegridadModel()
    {
        parent::ZendExt_Model();
    }

    public function adicionarSegChequeointegridad($instance)
    {

        try {
            $instance->save();
        } catch (Exception $e) {
            print_r($e);
        }

        return true;
    }

    public function modificarSegChequeointegridad($datos, $hash)
    {


        $objChequeo = SegChequeointegridad::obtainTableById(
            $datos[0]['idchequeo']
        );

        $objChequeo->hash = $hash;

        $fecha = new DateTime();

        $objChequeo->hora = $fecha->format('H:i:s');
        $objChequeo->fecha = $fecha->format('Y-m-d');

        $objChequeo->save();

        return true;
    }

    public function eliminarSegChequeointegridad($instance)
    {
        $instance->delete();

        return true;
    }
}